using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class VolumeSamplerOperations:RefCounted
{
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var result)?result:fallback;
    public Settings failure(string message)=>new Settings{["points"]=Array.Empty<Vector3>(),["error"]=message};
    private static bool Before(Vector3 a,Vector3 b)=>a.X!=b.X?a.X<b.X:a.Y!=b.Y?a.Y<b.Y:a.Z<b.Z;
    public Settings closed_mesh(Settings geometry)
    {
        var faces=new List<Vector3>();var edges=new Dictionary<(Vector3,Vector3),Vector2I>();var fans=new Dictionary<Vector3,Dictionary<Vector3,Vector3>>();foreach(var value in Get(geometry,"meshes",new Godot.Collections.Array()).AsGodotArray()){var item=value.AsGodotDictionary();foreach(var surface in Get(item,"surfaces",new Godot.Collections.Array()).AsGodotArray()){var arrays=surface.AsGodotArray();if(arrays.Count!=(int)Mesh.ArrayType.Max||arrays[(int)Mesh.ArrayType.Vertex].VariantType!=Variant.Type.PackedVector3Array)return failure("Unsupported mesh surface: triangle vertices are required.");var vertices=arrays[(int)Mesh.ArrayType.Vertex].AsVector3Array();var indices=arrays[(int)Mesh.ArrayType.Index].VariantType==Variant.Type.Nil?Array.Empty<int>():arrays[(int)Mesh.ArrayType.Index].AsInt32Array();int count=indices.Length>0?indices.Length:vertices.Length;if(count%3!=0)return failure("The source contains an incomplete triangle surface.");if((faces.Count+count)/3>100000)return failure("Source exceeds 100,000 triangles. Use a simpler closed source mesh.");var transform=item["local"].AsTransform3D();for(int i=0;i<count;i+=3){var points=new Vector3[3];var keys=new Vector3[3];for(int slot=0;slot<3;slot++){int index=indices.Length>0?indices[i+slot]:i+slot;if(index<0||index>=vertices.Length)return failure("The mesh has an invalid triangle index.");var point=transform*vertices[index];if(!point.IsFinite())return failure("The mesh contains non-finite vertices.");points[slot]=point;keys[slot]=point.Snapped(Vector3.One*.00001f);}if((points[1]-points[0]).Cross(points[2]-points[0]).LengthSquared()<1e-16||keys[0]==keys[1]||keys[1]==keys[2]||keys[2]==keys[0])return failure("The source has degenerate triangles. Clean the mesh before filling.");for(int slot=0;slot<3;slot++){var a=keys[slot];var b=keys[(slot+1)%3];var previous=keys[(slot+2)%3];bool forward=Before(a,b);var key=forward?(a,b):(b,a);edges.TryGetValue(key,out var entry);edges[key]=entry+new Vector2I(1,forward?1:-1);if(!fans.TryGetValue(a,out var fan))fans[a]=fan=new Dictionary<Vector3,Vector3>();if(fan.ContainsKey(b))return failure("The source is nonmanifold or has duplicate faces.");fan[b]=previous;}faces.AddRange(points);}}}
        if(faces.Count==0)return failure("Choose an actor containing a closed triangle mesh; this source has no supported triangles.");foreach(var edge in edges.Values){if(edge.X!=2)return failure("The source mesh is open or nonmanifold. Close its surface before filling.");if(edge.Y!=0)return failure("The source has inconsistent triangle winding. Recalculate its face orientation before filling.");}foreach(var fan in fans.Values){var first=fan.Keys.First();var current=first;var seen=new HashSet<Vector3>();while(fan.TryGetValue(current,out var next)&&seen.Add(current))current=next;if(current!=first||seen.Count!=fan.Count)return failure("The source has a nonmanifold vertex. Separate touching shells before filling.");}var mesh=new TriangleMesh();mesh.CreateFromFaces(faces.ToArray());var bounds=new Aabb(faces[0],Vector3.Zero);foreach(var point in faces)bounds=bounds.Expand(point);return new Settings{["mesh"]=mesh,["bounds"]=bounds,["error"]=""};
    }
    public bool inside(TriangleMesh mesh,Vector3 point,double distance){var direction=new Vector3(1,.173f,.317f).Normalized();var from=point;int count=0;for(int i=0;i<256;i++){var hit=mesh.IntersectRay(from,point+direction*(float)distance);if(hit.Count==0)return count%2==1;count++;from=hit["position"].AsVector3()+direction*.00001f;}return false;}
    public bool contains(Vector3 point,int shape,Vector3 size,TriangleMesh? mesh,Aabb bounds){if(!bounds.HasPoint(point))return false;var q=point/(size*.5f);if(shape==1)return q.LengthSquared()<=1;if(shape==2)return new Vector2(q.X,q.Z).LengthSquared()<=1;if(shape==3)return inside(mesh!,point,Math.Max(.001,bounds.Size.Length()*3));return true;}
    public Settings generate(int shape,Vector3 size,double spacing,int budget,Transform3D pose,Settings geometry,double jitter,long seed)
    {
        if(shape is not (0 or 1 or 2 or 3))return failure("Unsupported volume shape. Choose Box, Sphere, Cylinder or a closed mesh actor.");if(!size.IsFinite()||size.X<=0||size.Y<=0||size.Z<=0)return failure("Source dimensions must be positive and finite.");if(!double.IsFinite(spacing)||spacing<=0||budget<1)return failure("Grain spacing and maximum count must be positive.");if(!pose.Origin.IsFinite()||!pose.Basis.IsFinite()||Math.Abs(pose.Basis.Determinant())<1e-10)return failure("The source needs a finite, nonzero transform scale on every axis.");var bounds=new Aabb(-size*.5f,size);TriangleMesh? mesh=null;if(shape==3){var closed=closed_mesh(geometry);if(closed["error"].AsString().Length>0)return closed;mesh=closed["mesh"].As<TriangleMesh>();bounds=closed["bounds"].AsAabb();}var cells=bounds.Size/(float)spacing;if(!cells.IsFinite()||cells.X>200000||cells.Y>200000||cells.Z>200000)return failure("Source exceeds 200,000 sampling cells. Increase spacing or shrink the source.");var n=new Vector3I(Mathf.CeilToInt(cells.X),Mathf.CeilToInt(cells.Y),Mathf.CeilToInt(cells.Z));if((long)n.X*n.Y*n.Z>200000)return failure("Source exceeds 200,000 sampling cells. Increase spacing or shrink the source.");var points=new List<Vector3>();var rng=new RandomNumberGenerator{Seed=unchecked((ulong)seed)};for(int x=0;x<n.X;x++)for(int y=0;y<n.Y;y++)for(int z=0;z<n.Z;z++){var point=bounds.Position+(new Vector3(x,y,z)+Vector3.One*.5f)*(float)spacing;if(!contains(point,shape,size,mesh,bounds))continue;if(jitter>0){var candidate=point+new Vector3(rng.RandfRange(-1,1),rng.RandfRange(-1,1),rng.RandfRange(-1,1))*(float)(spacing*jitter);if(contains(candidate,shape,size,mesh,bounds))point=candidate;}if(points.Count>=budget)return failure("Initial volume exceeds the grain/particle budget. Increase spacing or raise the maximum count; no partial fill was created.");points.Add(pose*point);}if(points.Count==0)return failure("No interior samples fit at this spacing. Decrease spacing or enlarge the source.");return new Settings{["points"]=points.ToArray(),["error"]=""};
    }
}
